<?php
namespace App\Services;use App\Models\InventoryItem;use App\Models\PosSale;use App\Models\ProductVariant;use App\Models\StockMovement;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;use Illuminate\Validation\ValidationException;
class PosService{public function sell(array $data,int $userId):PosSale{return DB::transaction(function()use($data,$userId){$subtotal=0;$lines=[];foreach($data['items'] as $input){$v=ProductVariant::with('product')->findOrFail($input['variant_id']);$stock=InventoryItem::where('product_variant_id',$v->id)->where('inventory_location_id',$data['inventory_location_id'])->lockForUpdate()->firstOrFail();$qty=(float)$input['quantity'];if((float)$stock->quantity_on_hand-(float)$stock->quantity_reserved<$qty)throw ValidationException::withMessages(['stock'=>"Insufficient stock: {$v->sku}"]);$stock->decrement('quantity_on_hand',$qty);$price=(float)$v->price;$subtotal+=$price*$qty;$lines[]=compact('v','qty','price','stock');}$total=$subtotal-(float)($data['discount_total']??0);$sale=PosSale::create(['uuid'=>(string)Str::uuid(),'number'=>'POS-'.now()->format('ymdHis'),'user_id'=>$userId,'inventory_location_id'=>$data['inventory_location_id'],'payment_method'=>$data['payment_method'],'subtotal'=>$subtotal,'discount_total'=>$data['discount_total']??0,'grand_total'=>$total,'paid_amount'=>$data['paid_amount'],'change_amount'=>max(0,$data['paid_amount']-$total),'sold_at'=>now()]);foreach($lines as $l){$v=$l['v'];$sale->items()->create(['product_variant_id'=>$v->id,'sku'=>$v->sku,'product_name'=>$v->product->name,'quantity'=>$l['qty'],'unit_price'=>$l['price'],'line_total'=>$l['qty']*$l['price']]);StockMovement::create(['uuid'=>(string)Str::uuid(),'product_variant_id'=>$v->id,'inventory_location_id'=>$data['inventory_location_id'],'type'=>'pos_sale','quantity'=>-$l['qty'],'unit_cost'=>$l['stock']->average_cost,'balance_after'=>$l['stock']->fresh()->quantity_on_hand,'reference_type'=>PosSale::class,'reference_id'=>$sale->id,'created_by'=>$userId,'occurred_at'=>now()]);}return $sale->fresh('items');},3);}}
